CREATE DATABASE IF NOT EXISTS wms_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE wms_db;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS rfid_mappings, audit_logs, stock_movements, transfer_items, transfers, order_items, orders, inventory, product_serials, product_batches, locations, warehouses, suppliers, products, roles, users, clients;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) NOT NULL UNIQUE, permissions JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role_id BIGINT UNSIGNED NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, last_login_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_users_role FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE clients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, client_code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, billing_config JSON NULL, is_active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE suppliers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, supplier_code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, contact_person VARCHAR(120) NULL, phone VARCHAR(40) NULL, email VARCHAR(160) NULL, address TEXT NULL, is_active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE warehouses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, warehouse_code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, address TEXT NULL, timezone VARCHAR(60) NOT NULL DEFAULT 'Asia/Jakarta', is_active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE locations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, warehouse_id BIGINT UNSIGNED NOT NULL, location_code VARCHAR(60) NOT NULL, zone VARCHAR(60) NULL, aisle VARCHAR(30) NULL, rack VARCHAR(30) NULL, shelf VARCHAR(30) NULL, bin_code VARCHAR(30) NULL, location_type ENUM('RECEIVING','STORAGE','PICKING','PACKING','DISPATCH','QUARANTINE','RETURNS') NOT NULL DEFAULT 'STORAGE', capacity_qty DECIMAL(14,3) NULL, is_active TINYINT(1) DEFAULT 1, UNIQUE KEY uq_location(warehouse_id,location_code), CONSTRAINT fk_locations_wh FOREIGN KEY(warehouse_id) REFERENCES warehouses(id)) ENGINE=InnoDB;
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sku VARCHAR(80) NOT NULL UNIQUE, barcode VARCHAR(100) NULL UNIQUE, name VARCHAR(200) NOT NULL, description TEXT NULL, category VARCHAR(100) NULL, uom VARCHAR(20) NOT NULL DEFAULT 'PCS', tracking_mode ENUM('NONE','BATCH','SERIAL','BATCH_EXPIRY','SERIAL_EXPIRY') NOT NULL DEFAULT 'NONE', safety_stock DECIMAL(14,3) NOT NULL DEFAULT 0, buffer_stock DECIMAL(14,3) NOT NULL DEFAULT 0, reorder_point DECIMAL(14,3) NOT NULL DEFAULT 0, default_client_id BIGINT UNSIGNED NULL, is_active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_product_client FOREIGN KEY(default_client_id) REFERENCES clients(id)) ENGINE=InnoDB;
CREATE TABLE product_batches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, batch_no VARCHAR(100) NOT NULL, expiry_date DATE NULL, manufactured_date DATE NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_batch(product_id,batch_no), CONSTRAINT fk_batch_product FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE product_serials (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, serial_no VARCHAR(120) NOT NULL UNIQUE, batch_id BIGINT UNSIGNED NULL, status ENUM('AVAILABLE','RESERVED','SHIPPED','DAMAGED','QUARANTINE') NOT NULL DEFAULT 'AVAILABLE', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_serial_product FOREIGN KEY(product_id) REFERENCES products(id), CONSTRAINT fk_serial_batch FOREIGN KEY(batch_id) REFERENCES product_batches(id)) ENGINE=InnoDB;
CREATE TABLE inventory (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, warehouse_id BIGINT UNSIGNED NOT NULL, location_id BIGINT UNSIGNED NULL, batch_id BIGINT UNSIGNED NULL, qty_on_hand DECIMAL(14,3) NOT NULL DEFAULT 0, qty_reserved DECIMAL(14,3) NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_inventory(product_id,warehouse_id,location_id,batch_id), CONSTRAINT fk_inv_product FOREIGN KEY(product_id) REFERENCES products(id), CONSTRAINT fk_inv_wh FOREIGN KEY(warehouse_id) REFERENCES warehouses(id), CONSTRAINT fk_inv_location FOREIGN KEY(location_id) REFERENCES locations(id), CONSTRAINT fk_inv_batch FOREIGN KEY(batch_id) REFERENCES product_batches(id), CHECK(qty_on_hand >= 0), CHECK(qty_reserved >= 0 AND qty_reserved <= qty_on_hand)) ENGINE=InnoDB;
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_no VARCHAR(60) NOT NULL UNIQUE, order_type ENUM('B2B','B2C','CONSIGNMENT') NOT NULL DEFAULT 'B2B', direction ENUM('INBOUND','OUTBOUND') NOT NULL, client_id BIGINT UNSIGNED NULL, supplier_id BIGINT UNSIGNED NULL, warehouse_id BIGINT UNSIGNED NOT NULL, status ENUM('DRAFT','SCHEDULED','RECEIVING','PICKING','PACKING','READY_TO_DISPATCH','DISPATCHED','COMPLETED','CANCELLED') NOT NULL DEFAULT 'DRAFT', priority ENUM('LOW','NORMAL','HIGH','URGENT') NOT NULL DEFAULT 'NORMAL', scheduled_at DATETIME NULL, reference_no VARCHAR(100) NULL, notes TEXT NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(client_id) REFERENCES clients(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id), FOREIGN KEY(warehouse_id) REFERENCES warehouses(id), FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, location_id BIGINT UNSIGNED NULL, batch_id BIGINT UNSIGNED NULL, qty_expected DECIMAL(14,3) NOT NULL, qty_processed DECIMAL(14,3) NOT NULL DEFAULT 0, unit_price DECIMAL(14,2) NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(location_id) REFERENCES locations(id), FOREIGN KEY(batch_id) REFERENCES product_batches(id), CHECK(qty_expected > 0), CHECK(qty_processed >= 0)) ENGINE=InnoDB;
CREATE TABLE transfers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transfer_no VARCHAR(60) NOT NULL UNIQUE, from_warehouse_id BIGINT UNSIGNED NOT NULL, to_warehouse_id BIGINT UNSIGNED NOT NULL, status ENUM('DRAFT','IN_TRANSIT','RECEIVED','CANCELLED') NOT NULL DEFAULT 'DRAFT', requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, dispatched_at DATETIME NULL, received_at DATETIME NULL, notes TEXT NULL, created_by BIGINT UNSIGNED NULL, FOREIGN KEY(from_warehouse_id) REFERENCES warehouses(id), FOREIGN KEY(to_warehouse_id) REFERENCES warehouses(id), FOREIGN KEY(created_by) REFERENCES users(id), CHECK(from_warehouse_id <> to_warehouse_id)) ENGINE=InnoDB;
CREATE TABLE transfer_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transfer_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, from_location_id BIGINT UNSIGNED NULL, to_location_id BIGINT UNSIGNED NULL, batch_id BIGINT UNSIGNED NULL, qty DECIMAL(14,3) NOT NULL, FOREIGN KEY(transfer_id) REFERENCES transfers(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(from_location_id) REFERENCES locations(id), FOREIGN KEY(to_location_id) REFERENCES locations(id), FOREIGN KEY(batch_id) REFERENCES product_batches(id), CHECK(qty > 0)) ENGINE=InnoDB;
CREATE TABLE stock_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, movement_no VARCHAR(70) NOT NULL UNIQUE, movement_type ENUM('OPENING','INBOUND','OUTBOUND','TRANSFER_OUT','TRANSFER_IN','ADJUSTMENT','RETURN','DAMAGE') NOT NULL, product_id BIGINT UNSIGNED NOT NULL, warehouse_id BIGINT UNSIGNED NOT NULL, location_id BIGINT UNSIGNED NULL, batch_id BIGINT UNSIGNED NULL, qty_change DECIMAL(14,3) NOT NULL, reference_type VARCHAR(40) NULL, reference_id BIGINT UNSIGNED NULL, reference_no VARCHAR(100) NULL, notes VARCHAR(500) NULL, performed_by BIGINT UNSIGNED NULL, occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_movement_date(occurred_at), INDEX idx_movement_product(product_id,warehouse_id), FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(warehouse_id) REFERENCES warehouses(id), FOREIGN KEY(location_id) REFERENCES locations(id), FOREIGN KEY(batch_id) REFERENCES product_batches(id), FOREIGN KEY(performed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE rfid_mappings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uid VARCHAR(160) NOT NULL UNIQUE, product_id BIGINT UNSIGNED NOT NULL, reader_name VARCHAR(120) NULL, notes VARCHAR(500) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_by BIGINT UNSIGNED NULL, deactivated_by BIGINT UNSIGNED NULL, deactivation_reason VARCHAR(250) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deactivated_at DATETIME NULL, INDEX idx_rfid_product(product_id,is_active), CONSTRAINT fk_rfid_product FOREIGN KEY(product_id) REFERENCES products(id), CONSTRAINT fk_rfid_created_by FOREIGN KEY(created_by) REFERENCES users(id), CONSTRAINT fk_rfid_deactivated_by FOREIGN KEY(deactivated_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, action VARCHAR(80) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, before_data JSON NULL, after_data JSON NULL, ip_address VARCHAR(45) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_date(created_at), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
INSERT INTO roles(name,permissions) VALUES ('Administrator',JSON_ARRAY('*')),('Warehouse Operator',JSON_ARRAY('dashboard','inventory','products','movements','orders','transfers','reports')),('Viewer',JSON_ARRAY('dashboard','inventory','products','movements','reports'));
